//! Deterministic rendering.
//!
//! Everything here is byte-for-byte reproducible: same packs plus same overrides produce
//! the same files. That is what makes `--check` a meaningful gate rather than a hint.

use serde::{Deserialize, Serialize};

use jcs_gates::ParserKind;

use crate::error::Result;
use crate::loader::sha256_hex;
use crate::model::Composition;

/// First line of every file we own, used to detect hand-edited files.
pub const GENERATED_MARKER: &str =
    "<!-- generated by jcs policy render; edit .jcs/policy.toml instead -->";

pub const AGENTS_PATH: &str = "AGENTS.md";
pub const GATES_PATH: &str = ".jcs/gates.toml";
pub const LOCK_PATH: &str = ".jcs/policy.lock";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RenderedFile {
    pub path: String,
    pub content: String,
    pub sha256: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rendered {
    pub files: Vec<RenderedFile>,
    pub lock: Lockfile,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Lockfile {
    pub version: u32,
    pub render_hash: String,
    #[serde(default)]
    pub pack: Vec<LockedPack>,
    #[serde(default)]
    pub file: Vec<LockedFile>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct LockedPack {
    pub id: String,
    pub version: String,
    pub hash: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct LockedFile {
    pub path: String,
    pub hash: String,
}

/// Renders every generated file for a composition.
pub fn render(composition: &Composition, policy_source: &str) -> Result<Rendered> {
    let agents = render_agents(composition, policy_source);
    let gates = render_gates(composition)?;

    let mut files = Vec::new();
    for (path, content) in [(AGENTS_PATH, agents), (GATES_PATH, gates)] {
        files.push(RenderedFile {
            path: path.to_string(),
            sha256: format!("sha256:{}", sha256_hex(&content)),
            content,
        });
    }

    let render_hash = {
        let mut canonical = String::new();
        for file in &files {
            canonical.push_str(&file.path);
            canonical.push('\0');
            canonical.push_str(&file.content);
            canonical.push('\0');
        }
        format!("sha256:{}", sha256_hex(&canonical))
    };

    let lock = Lockfile {
        version: 1,
        render_hash,
        pack: composition
            .packs
            .iter()
            .map(|pack| LockedPack {
                id: pack.id.clone(),
                version: pack.version.clone(),
                hash: pack.hash.clone(),
            })
            .collect(),
        file: files
            .iter()
            .map(|file| LockedFile {
                path: file.path.clone(),
                hash: file.sha256.clone(),
            })
            .collect(),
    };

    let lock_content = render_lock(&lock)?;
    files.push(RenderedFile {
        path: LOCK_PATH.to_string(),
        sha256: format!("sha256:{}", sha256_hex(&lock_content)),
        content: lock_content,
    });

    Ok(Rendered { files, lock })
}

fn render_agents(composition: &Composition, policy_source: &str) -> String {
    let mut out = String::new();

    out.push_str(GENERATED_MARKER);
    out.push('\n');
    out.push_str(&format!("<!-- source: {policy_source} -->\n"));
    out.push_str(&format!(
        "<!-- packs: {} -->\n\n",
        composition.pack_ids().join(", ")
    ));

    out.push_str("# Project instructions\n\n");
    out.push_str(
        "This file is generated. Edit `.jcs/policy.toml` and run `jcs policy render` \
         instead of editing it by hand.\n\n",
    );

    out.push_str("## Active packs\n\n");
    for pack in &composition.packs {
        out.push_str(&format!(
            "- `{}` {} — {}\n",
            pack.id, pack.version, pack.description
        ));
    }
    out.push('\n');

    out.push_str("## Rules\n\n");
    for (key, entry) in &composition.rules {
        out.push_str(&format!(
            "- **{}** ({}) — {}\n",
            key, entry.source, entry.value
        ));
    }
    out.push('\n');

    if !composition.skills.is_empty() {
        out.push_str("## Skills\n\n");
        for skill in &composition.skills {
            out.push_str(&format!("- `{skill}`\n"));
        }
        out.push('\n');
    }

    for doc in &composition.instructions {
        out.push_str(&format!(
            "## {} {} ({})\n\n",
            doc.pack_id, doc.pack_version, doc.path
        ));
        out.push_str(doc.content.trim_end());
        out.push_str("\n\n");
    }

    out
}

#[derive(Serialize)]
struct GatesDocument {
    version: u32,
    gate: Vec<GateDocument>,
}

#[derive(Serialize)]
struct GateDocument {
    name: String,
    command: Vec<String>,
    timeout_secs: u64,
    required: bool,
    parser: ParserKind,
    #[serde(skip_serializing_if = "Option::is_none")]
    min_coverage: Option<f64>,
}

fn render_gates(composition: &Composition) -> Result<String> {
    let document = GatesDocument {
        version: 1,
        gate: composition
            .gates
            .iter()
            .map(|(name, entry)| GateDocument {
                name: name.clone(),
                command: entry.def.command.clone(),
                timeout_secs: entry.def.timeout.as_secs(),
                required: entry.def.required,
                parser: entry.def.parser,
                min_coverage: entry.def.min_coverage.map(|value| value.0),
            })
            .collect(),
    };

    let body = toml::to_string_pretty(&document)?;
    Ok(format!(
        "# {GENERATED_MARKER}\n# Source: .jcs/policy.toml\n\n{body}"
    ))
}

fn render_lock(lock: &Lockfile) -> Result<String> {
    let body = toml::to_string_pretty(lock)?;
    Ok(format!(
        "# Generated by jcs policy render. Commit this file: it pins what was rendered.\n\n{body}"
    ))
}

impl Lockfile {
    pub fn parse(content: &str) -> Result<Self> {
        Ok(toml::from_str(content)?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::compose::{compose, Overrides};
    use crate::loader::builtin_packs;
    use crate::resolve::resolve;

    fn composition() -> Composition {
        let packs = builtin_packs().unwrap();
        let resolved = resolve(&["rust-service".to_string()], &packs, &[]).unwrap();
        compose(&resolved, &Overrides::default())
    }

    fn content_of<'a>(rendered: &'a Rendered, path: &str) -> &'a str {
        &rendered
            .files
            .iter()
            .find(|file| file.path == path)
            .unwrap_or_else(|| panic!("missing rendered file {path}"))
            .content
    }

    #[test]
    fn rendering_twice_produces_identical_bytes() {
        let composition = composition();
        let first = render(&composition, ".jcs/policy.toml").unwrap();
        let second = render(&composition, ".jcs/policy.toml").unwrap();
        assert_eq!(first, second);
    }

    #[test]
    fn agents_md_carries_the_marker_packs_and_rule_provenance() {
        let rendered = render(&composition(), ".jcs/policy.toml").unwrap();
        let agents = content_of(&rendered, AGENTS_PATH);

        assert!(agents.starts_with(GENERATED_MARKER));
        assert!(agents.contains("`rust-service` 1.0.0"));
        assert!(agents.contains("`core-git` 1.0.0"));
        assert!(agents.contains("**no_unwrap_outside_tests** (rust-service)"));
        assert!(agents.contains("## core-git 1.0.0 (instructions.md)"));
    }

    #[test]
    fn gates_toml_round_trips_to_the_same_gate_set() {
        #[derive(Deserialize)]
        struct Document {
            version: u32,
            gate: Vec<Entry>,
        }
        #[derive(Deserialize)]
        struct Entry {
            name: String,
            command: Vec<String>,
            timeout_secs: u64,
            required: bool,
        }

        let composition = composition();
        let rendered = render(&composition, ".jcs/policy.toml").unwrap();
        let parsed: Document = toml::from_str(content_of(&rendered, GATES_PATH)).unwrap();

        assert_eq!(parsed.version, 1);
        assert_eq!(parsed.gate.len(), composition.gates.len());

        for entry in parsed.gate {
            let expected = &composition.gates[&entry.name].def;
            assert_eq!(entry.command, expected.command);
            assert_eq!(entry.timeout_secs, expected.timeout.as_secs());
            assert_eq!(entry.required, expected.required);
        }
    }

    #[test]
    fn the_lock_pins_every_pack_and_generated_file() {
        let composition = composition();
        let rendered = render(&composition, ".jcs/policy.toml").unwrap();

        assert_eq!(rendered.lock.pack.len(), composition.packs.len());
        for pack in &rendered.lock.pack {
            assert!(pack.hash.starts_with("sha256:"));
            assert!(!pack.version.is_empty());
        }

        for file in [AGENTS_PATH, GATES_PATH] {
            let hash = &rendered
                .lock
                .file
                .iter()
                .find(|locked| locked.path == file)
                .unwrap()
                .hash;
            let actual = format!("sha256:{}", sha256_hex(content_of(&rendered, file)));
            assert_eq!(*hash, actual, "lock hash mismatch for {file}");
        }

        // The lock is itself parseable, which is what `--check` relies on.
        let parsed = Lockfile::parse(content_of(&rendered, LOCK_PATH)).unwrap();
        assert_eq!(parsed, rendered.lock);
    }

    #[test]
    fn changing_a_rule_changes_the_rendered_output() {
        let mut composition = composition();
        let before = render(&composition, ".jcs/policy.toml").unwrap();

        composition.rules.insert(
            "no_unwrap_outside_tests".into(),
            crate::model::RuleEntry {
                value: "changed".into(),
                source: "project".into(),
            },
        );

        let after = render(&composition, ".jcs/policy.toml").unwrap();
        assert_ne!(before.lock.render_hash, after.lock.render_hash);
        assert_ne!(
            content_of(&before, AGENTS_PATH),
            content_of(&after, AGENTS_PATH)
        );
    }
}
